const SPARE_PICK_RE = /^F\d+ spare pick: /

/**
 * The cell's own read - the spare pick's raw colon count across the
 * lines. The spare pick book's own colon seat's count - the count
 * this word prices across the faces (the whole raw mass the lane
 * prints - every line rides, no exclusion the lane needs).
 *
 * @param {string[]|null} [lines] the face's own log lines
 * @returns {number} the spare pick raw colon count (0 when the
 *   lines cannot prove a spare pick line - the zero a lawful count)
 */
export function sparePickColons (lines) {
  if (!Array.isArray(lines)) return 0
  let n = 0
  for (const l of lines) {
    if (typeof l === 'string' && SPARE_PICK_RE.test(l)) n++
  }
  return n
}

/**
 * The fence - the fold's own image must prove itself before the word
 * rides. A fold that cannot prove itself prices nothing (the fence
 * law: the word never rides a lie). The zero count is lawful (the
 * smelt lane's own zero precedent). The fence never rejects extra
 * keys.
 *
 * @param {object|null} [e] the trend fold:
 *   { back: {sparePickColons}, prev: {sparePickColons}, cur: {sparePickColons} }
 * @returns {boolean}
 */
export function sparePickColonTrendConsistent (e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return false
  const faceOk = (s) => {
    if (!s || typeof s !== 'object' || Array.isArray(s)) return false
    return Number.isInteger(s.sparePickColons) && s.sparePickColons >= 0
  }
  return faceOk(e.back) && faceOk(e.prev) && faceOk(e.cur)
}

